/** Column options for the useColumnAlignment plugin hook. */
export interface UseAlignmentColumnOptions {
    /** Alignment of the text within the column. */
    alignment?: 'left' | 'center' | 'right' | 'top-left' | 'top-center' | 'top-right' | 'bottom-left' | 'bottom-center' | 'bottom-right';
}
/** Defines props added to columns when useColumnAlignment plugin hook is used. */
export interface UseAlignmentColumnProps {
    /** Defines the alignment of the text within the column. */
    alignment?: 'left' | 'center' | 'right' | 'top-left' | 'top-center' | 'top-right' | 'bottom-left' | 'bottom-center' | 'bottom-right';
}
